// lib-alert-base: the calling playbook's alert, lib-config, route and context.
// The context (playbook name, its execution id) goes to TheHive and the
// writeback as before: sub-workflows have their own execution ids.
const input = $input.first().json;
if (!input.config || !input.config.writeback) throw new Error('lib-alert-base needs the lib-config output as `config`');
if (!input.context || typeof input.context.playbook !== 'string') throw new Error('lib-alert-base needs the calling playbook\'s `context` ({playbook, n8n_execution_id, recv_execution_id})');
return [{ json: {
  alert: input.alert,
  config: input.config,
  context: input.context,
  // From lib-route-alert (N8N-1.3); null when called without a route.
  route: input.route ?? null,
} }];

// C10 (N8N-2.11): one MISP warninglist call for the alert's observables, before
// the TheHive alert is created, so the tags travel in its body.
const c = $('Context').first().json;
return [{ json: { observables: $input.first().json.observables, config: c.config, context: c.context } }];

const c = $('Context').first().json;
const ex = $('Extract observables (lib-extract-observables)').first().json;
// Observables as tagged by lib-misp-warninglist (C10); the extraction's own when
// the lib failed unexpectedly (On Error = continue: its item is then {error}).
const wl = $('Warninglists (lib-misp-warninglist)').first().json;
const observables = Array.isArray(wl.observables) ? wl.observables : ex.observables;
return [{ json: {
  canonical: $('Normalize (lib-normalize-wazuh-alert)').first().json.canonical,
  extraction: { ...ex, observables },
  config: c.config, context: c.context, route: c.route,
} }];

// Only a newly created alert is enriched (a duplicate was enriched when it was
// created). TLP / PAP are the alert's (lib-config), checked against each
// analyzer's max by lib-enrich-observable. severity: as sent to TheHive (D-N7,
// VirusTotal's severe path); enrichment_started_ms: the budget's start (D-N8).
const c = $('Context').first().json;
const u = $input.first().json;
const ex = $('Extract observables (lib-extract-observables)').first().json;
// Observables as tagged by lib-misp-warninglist (C10); the extraction's own when
// the lib failed unexpectedly (On Error = continue: its item is then {error}).
const wl = $('Warninglists (lib-misp-warninglist)').first().json;
const observables = Array.isArray(wl.observables) ? wl.observables : ex.observables;
return [{ json: {
  thehive_alert_id: u.thehive_alert_id, wazuh_alert_id: u.wazuh_alert_id,
  observables, tlp: c.config.tlp, pap: c.config.pap,
  severity: u.severity, enrichment_started_ms: Date.now(),
  config: c.config, context: c.context,
} }];

// The TheHive alert already existed (duplicate sourceRef). Does it have its
// writeback? If not, an earlier run stopped before writing it (n8n crashed or
// restarted, N8N-1.4): this run completes it.
const c = $('Context').first().json;
const u = $input.first().json;
return [{ json: { thehive_alert_id: u.thehive_alert_id, wazuh_alert_id: u.wazuh_alert_id, config: c.config } }];

// Completing an interrupted run (N8N-1.4): observables already enriched before
// the interruption (a tag with the analyzer prefix on the TheHive observable)
// are not sent again; the others go through the same policy as a new alert,
// with the alert's severity as TheHive has it (D-N7) and a budget counted from
// this call (D-N8: the interrupted run's start isn't stored).
const c = $('Context').first().json;
const u = $('Upsert (lib-thehive-upsert-alert)').first().json;
const st = $input.first().json;
const ex = $('Extract observables (lib-extract-observables)').first().json;
// Observables as tagged by lib-misp-warninglist (C10); the extraction's own when
// the lib failed unexpectedly (On Error = continue: its item is then {error}).
const wl = $('Warninglists (lib-misp-warninglist)').first().json;
const observables = Array.isArray(wl.observables) ? wl.observables : ex.observables;
const prefix = c.config.enrichment.tags.analyzer_prefix;
const key = (o) => `${o.dataType}:${o.data}`;
const done = new Set(st.observables.filter((o) => o.tags.some((t) => t.startsWith(prefix))).map(key));
return [{ json: {
  thehive_alert_id: u.thehive_alert_id, wazuh_alert_id: u.wazuh_alert_id,
  observables: observables.filter((o) => !done.has(key(o))),
  already_enriched: observables.filter((o) => done.has(key(o))).map((o) => `${o.dataType} ${o.data}`),
  tlp: c.config.tlp, pap: c.config.pap, severity: u.severity, enrichment_started_ms: Date.now(),
  config: c.config, context: c.context,
} }];

// Normalize or upsert handed the alert to lib-error, which parked it.
const r = $input.first().json;
const alert = $('Context').first().json.alert;
return [{ json: {
  ok: false,
  outcome: 'parked',
  wazuh_alert_id: r.wazuh_alert_id ?? (typeof alert?.id === 'string' ? alert.id : null),
  error: r.error_class ?? r.stage ?? null,
  message: r.message ?? null,
  result: r,
} }];

// lib-config: THEHIVE_ENABLED=false (no cases node on this machine). Recorded,
// not parked: there is nothing to retry.
const u = $input.first().json;
return [{ json: {
  ok: false,
  outcome: 'skipped',
  status: 'skipped: TheHive not configured',
  wazuh_alert_id: u.wazuh_alert_id,
} }];

// The chain's result for the calling playbook. `actions`: the writeback's
// sections every playbook shares (route, TheHive alert, warninglists,
// enrichment), as pb-generic wrote them; the playbook adds its own lines
// and the "Systems changed" line, then calls lib-thehive-writeback.
// repair: the alert existed without a writeback and this run completed it (N8N-1.4).
const repair = $('Repair enrich input').isExecuted;
// Enrichment section (N8N-2.4): counts, then one line per observable.
function enrichmentLines(u) {
  if (u.duplicate && !repair) return ['Enrichment: not run (duplicate: enriched when the alert was created).'];
  if (!$('Enrich (lib-enrich-observable)').isExecuted) return ['Enrichment: not run.'];
  const e = $('Enrich (lib-enrich-observable)').first().json;
  // On Error = continue: an unexpected failure inside the lib arrives as {error}.
  if (e.ok !== true) return [`Enrichment: failed (unexpected error in lib-enrich-observable: ${e.error ?? 'no result'}); alert and writeback unaffected.`];
  const k = e.counts;
  // Analyzer runs not started, by reason (not enabled in Cortex, url not
  // absolute, severe path only, enrichment budget, ...).
  const byReason = Object.entries(k.skipped_runs ?? {});
  const nSkipped = byReason.reduce((a, [, n]) => a + n, 0);
  const skipSummary = nSkipped > 0 ? `${nSkipped} analyzer run(s) skipped (${byReason.map(([r, n]) => `${r}: ${n}`).join(', ')})` : '';
  const lines = [!e.cortex_called && k.enriched === 0 && k.failed === 0
    ? `Enrichment (Cortex, C6): nothing eligible (${k.skipped} observable(s) skipped${skipSummary ? `; ${skipSummary}` : ''}), no Cortex job.`
    : `Enrichment (Cortex, C6): ${k.enriched} enriched, ${k.skipped} skipped, ${k.failed} failed of ${k.observables} observable(s); ${k.jobs} analyzer run(s)${k.jobs_from_cache ? ` (${k.jobs_from_cache} answered from Cortex's cache)` : ''}${skipSummary ? `; ${skipSummary}` : ''}.`];
  // D-N8: one line when the budget stopped new jobs.
  if (e.budget?.hit) lines.push(`Enrichment budget reached (D-N8): ${e.budget.budget_s} s; ${e.budget.used_s} s used, ${e.budget.skipped} analyzer run(s) not started.`);
  const fails = (fs) => fs.map((f) => `${f.analyzer}: ${f.class}${f.attempts ? ` after ${f.attempts} call(s)` : ''}${f.job_id ? `, job ${f.job_id}` : ''}`).join('; ');
  const skips = (ss) => (ss ?? []).map((s) => `${s.analyzer}: skipped (${s.reason})`).join('; ');
  for (const o of e.observables) {
    const name = `${o.dataType} ${o.data}`;
    if (o.status === 'enriched') {
      const runs = o.results.map((r) => `${r.analyzer}: ${r.verdict}, ${r.taxonomies.join('; ') || 'no taxonomy'}, job ${r.job_id}${r.from_cache ? ' (cached)' : ''}`).join(' | ');
      const te = o.tag_error;
      lines.push(`Enriched: ${name}: verdict ${o.verdict} (${runs}); ` + (o.tagged
        ? `tagged ${o.add_tags.join(', ')}${o.ioc ? ', marked IOC' : ''}.`
        : `verdict NOT written to TheHive (${te.class}${te.attempts ? ` after ${te.attempts} call(s)` : ''}).`));
      if (o.failed.length > 0) lines.push(`  Also failed for ${name}: ${fails(o.failed)}.`);
      if (o.skipped?.length > 0) lines.push(`  Skipped for ${name}: ${skips(o.skipped)}.`);
    } else if (o.status === 'failed') {
      lines.push(`Enrichment failed: ${name}: ${fails(o.failed)}.`);
      if (o.skipped?.length > 0) lines.push(`  Skipped for ${name}: ${skips(o.skipped)}.`);
    } else {
      lines.push(`Not enriched: ${name}: ${[...o.reasons, skips(o.skipped)].filter(Boolean).join('; ')}.`);
    }
  }
  for (const wmsg of e.warnings ?? []) lines.push(`Enrichment warning: ${wmsg}.`);
  return lines;
}
// Warninglist section (C10, N8N-2.11): a summary, then one line per match. On
// a duplicate the check ran (it comes before the upsert) but wrote no tags.
function warninglistLines(u) {
  const w = $('Warninglists (lib-misp-warninglist)').first().json;
  // On Error = continue: an unexpected failure inside the lib arrives as {error}.
  if (typeof w.ok !== 'boolean') return [`Warninglist check (MISP, C10): not done (unexpected error in lib-misp-warninglist: ${w.error ?? 'no result'}); alert unaffected.`];
  if (!w.ok) return [`Warninglist check (MISP, C10): not done (${w.class}); alert unaffected.`];
  if (!w.checked) return [w.skip_reason === 'disabled'
    ? 'Warninglist check (MISP, C10): not run (disabled in lib-config).'
    : 'Warninglists (MISP, C10): nothing to check (no eligible value), no MISP call.'];
  const k = w.counts;
  const lines = [`Warninglists (MISP, C10): ${k.matched} of ${k.checked} checked value(s) on a warninglist`
    + (k.matched > 0 ? '; a match means common, not safe: severity and status unchanged.' : '.')
    + (u.duplicate && k.matched > 0 ? ' Checked, tags not written (alert already existed).' : '')];
  const SHOWN = 10;
  for (const m of w.matches) {
    const names = m.lists.slice(0, SHOWN).join('; ') + (m.lists.length > SHOWN ? `; +${m.lists.length - SHOWN} more` : '');
    lines.push(`On warninglist: ${m.dataType} ${m.data}: ${names}` + (u.duplicate ? '.' : `; tagged ${m.add_tags.join(', ')}.`));
  }
  return lines;
}
const c = $('Context').first().json;
const u = $('Upsert (lib-thehive-upsert-alert)').first().json;
const actions = [];
const r = c.route;
if (r) {
  actions.push(`Route: ${r.route_id} (${r.matched_by}): playbook ${r.playbook}, case template ${r.case_template}.`);
  if (r.fallback) actions.push(`Playbook fallback: the route names ${r.fallback.wanted}, not built yet; ${r.playbook} ran.`);
  for (const pm of r.proposed_match) actions.push(`Proposed route matched, not active yet (X-04, W1.3): ${pm.id} (${pm.matched_by}).`);
} else {
  actions.push('Route: none (playbook called without lib-route-alert): default case template.');
}
if (u.duplicate) {
  actions.push(`TheHive alert already existed for Wazuh alert ${u.wazuh_alert_id} (duplicate sourceRef): nothing created.`);
  if (u.after_retry) actions.push('The create call was retried (timeout or TheHive error): the alert may have been created by the first call.');
  if (repair) {
    actions.push('Completed an interrupted run: the alert existed without a writeback (n8n stopped before writing it, N8N-1.4); enrichment ran now for the observables not enriched before.');
    const already = $('Repair enrich input').first().json.already_enriched;
    if (already.length > 0) actions.push(`Already enriched before the interruption (not sent again): ${already.join(', ')}.`);
  } else if ($('Alert state (lib-thehive-alert-state)').isExecuted && $('Alert state (lib-thehive-alert-state)').first().json.ok !== true) {
    const st = $('Alert state (lib-thehive-alert-state)').first().json;
    actions.push(`Writeback check before a repair failed (${st.stage ?? st.error ?? 'unexpected error'}): no repair attempted.`);
  }
} else {
  actions.push(`TheHive alert created: source ${u.source}, severity ${u.severity}, case template requested ${u.case_template}, observables: ${u.observables.join(', ') || 'none'}.`);
  for (const s of u.skipped_observables) actions.push(`Observable not sent: ${s.dataType} ${s.data} (${s.reason}).`);
  for (const wmsg of u.warnings) actions.push(`Warning: ${wmsg}.`);
}
actions.push(...warninglistLines(u));
actions.push(...enrichmentLines(u));
// C11 (N8N-2.9): the asox-metrics document, written by lib-thehive-writeback
// before its comment. Created (or repaired: the earlier run stopped before
// its writeback, so before the document): every creation field; t_event = the
// Wazuh alert's timestamp, t_alert = TheHive's _createdAt (never n8n's clock),
// both written only when missing. Duplicate: n8n_execution_id only.
const canonical = $('Normalize (lib-normalize-wazuh-alert)').first().json.canonical;
const mc = c.config.metrics;
const run = (canonical.full_log ?? '').match(new RegExp(mc.attack_start.run_pattern));
const executionId = String(c.context.n8n_execution_id);
const metrics = u.duplicate && !repair
  ? { mode: 'update', alert_id: u.wazuh_alert_id, source: u.source, fields: { n8n_execution_id: executionId } }
  : { mode: 'create', alert_id: u.wazuh_alert_id, source: u.source, attack_run_id: run ? run[1] : null,
    fields: {
      thehive_alert_id: u.thehive_alert_id, rule_id: canonical.rule.id, rule_level: canonical.rule.level,
      severity: u.severity, playbook: c.context.playbook, n8n_execution_id: executionId,
      outcome: 'none', auto_promoted: false, t_event: canonical.date_ms, t_alert: u.created_at,
    } };
const ex = $('Extract observables (lib-extract-observables)').first().json;
// Observables as tagged by lib-misp-warninglist (C10); the extraction's own when
// the lib failed unexpectedly (On Error = continue: its item is then {error}).
const wl = $('Warninglists (lib-misp-warninglist)').first().json;
const observables = Array.isArray(wl.observables) ? wl.observables : ex.observables;
const enriched = $('Enrich (lib-enrich-observable)').isExecuted ? $('Enrich (lib-enrich-observable)').first().json : null;
return [{ json: {
  ok: true,
  // repaired: duplicate whose earlier run stopped before its writeback (N8N-1.4).
  outcome: u.duplicate ? (repair ? 'repaired' : 'duplicate') : 'created',
  wazuh_alert_id: u.wazuh_alert_id,
  thehive_alert_id: u.thehive_alert_id,
  canonical,
  observables,
  skipped_observables: ex.skipped ?? [],
  extraction: ex,
  warninglist: wl,
  upsert: u,
  alert_state: $('Alert state (lib-thehive-alert-state)').isExecuted ? $('Alert state (lib-thehive-alert-state)').first().json : null,
  repair: repair ? { already_enriched: $('Repair enrich input').first().json.already_enriched } : null,
  enrichment: enriched,
  // N8N-2.4: counts, `not run (duplicate)` or `failed` (unexpected; never parks).
  enrichment_summary: u.duplicate && !repair ? 'not run (duplicate)' : (enriched?.ok === true ? enriched.counts : 'failed'),
  writeback: { sections: actions, metrics },
} }];
